INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('51cf6966-a1fe-529c-8f02-cbcd41e96580', '9add137f-1c70-5ed5-ae00-5329d683ffb4', 'ca15b736-3447-5667-8247-c40294ad6906', '339edc7b-d7dd-58df-937e-7277c061a79a', 'Id', 'The immutable identity of the movement record. Used to trace planning, dispatch, execution, completion, exceptions, integrations, and audit history for one movement. Identifies the movement event/instruction; Container identifies the equipment and sourceSlot/targetSlot identify physical positions. Required because every movement must remain independently traceable. Must be unique: a save is rejected if another Container Movement already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7d590e50-c0d3-5b7a-949a-d5beaf2f7729', '9add137f-1c70-5ed5-ae00-5329d683ffb4', '17dfea61-8750-5100-b058-88b2e118c7f0', '339edc7b-d7dd-58df-937e-7277c061a79a', 'Movement Number', 'The human-facing operational reference for the movement. Used by planners, operators, dispatchers, supervisors, gate teams, and external systems. It identifies the operational work item and is distinct from containerNumber and containerMovementId. Required for human and integration traceability. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Container Movement already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4d1f015e-67f6-5b86-9d3e-4703ba044f03', '9add137f-1c70-5ed5-ae00-5329d683ffb4', '25da5823-93b9-55c2-844e-6b29f12d78db', '339edc7b-d7dd-58df-937e-7277c061a79a', 'Movement Type', 'Defines the operational purpose and physical consequence of the movement. Determines validation, required source/target context, equipment needs, workflow, capacity effects, and reporting. Explains why the container is moving; the related transaction supplies the broader business reason when one exists. Establishes controlled receipt of a container into a facility or receiving flow. Places a container into a yard storage position. Relocates a container between yard positions to improve access, safety, capacity, or operational efficiency. Removes a container from a stacked position for another operation. Moves a container between controlled operational areas or locations. Records controlled exit through a facility gate. Records controlled entry through a facility gate. Places a container onto a transport asset for onward movement. Removes a container from a transport asset into the receiving flow. Positions equipment for inspection or survey. Moves equipment to or from a repair/workshop area. Required because the movement type determines physical and business rules. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('29eba209-1f9a-5b2b-8706-721c4e09c9d8', '9add137f-1c70-5ed5-ae00-5329d683ffb4', '2bbaa95f-8216-5cb1-80d3-f3c837ac8eaf', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Status', 'The execution state of the movement work item. Controls dispatch, assignment, execution, exception handling, and operational dashboards. Describes movement execution only; it must not be interpreted as the lifecycle status of the Container. Movement is required or scheduled but execution has not started. An operator, vehicle, crane, tractor, or other execution resource has been assigned. Physical execution has begun. The intended movement and resulting physical/transport state have been confirmed. The movement will not be executed under this instruction. Execution was attempted or initiated but did not complete successfully and requires recovery or replanning. Required for controlled operational execution. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fd9b28d1-c5e4-52f6-95c1-a6999a65b35d', '9add137f-1c70-5ed5-ae00-5329d683ffb4', '9aaca83f-254f-5f10-b1a1-6610d92686e0', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Planned At', 'The planned execution time for the movement. Supports yard sequencing, appointment coordination, crane/tractor scheduling, congestion management, and optimization. A planning timestamp is not evidence that movement occurred. Optional until a schedule is established.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d84c2d16-c23b-5fe0-909b-0b106692377b', '9add137f-1c70-5ed5-ae00-5329d683ffb4', 'a4fac908-d106-5905-aa1c-15cb40dc0c8f', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Started At', 'The timestamp when physical execution actually began. Supports productivity, equipment utilization, delay analysis, turnaround measurement, and audit. Represents actual execution and is distinct from plannedAt. Optional before execution or when supplied by an external execution system.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9383308b-2d97-5f2f-bf8a-07c1def36559', '9add137f-1c70-5ed5-ae00-5329d683ffb4', '3f2725f2-bd0b-5f32-8208-11aba5107f37', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Completed At', 'The timestamp when the intended movement was confirmed complete. Establishes completion chronology, move duration, resulting position/state, and operational metrics. For yard movements, completion should correspond to confirmed target-slot occupancy or source-slot release; for external movements it should correspond to the appropriate transport state. Optional until completion.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8094483e-4235-5b58-bc33-a688ed3324d6', '9add137f-1c70-5ed5-ae00-5329d683ffb4', '14b0287b-a993-5ab4-8d50-17909117f2c4', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Priority', 'The relative urgency used to sequence this movement against competing work. Used by dispatch, yard optimization, exception management, and operational scheduling. Priority influences scheduling order but does not change the movement''s physical meaning or the Container''s business importance. Can normally wait behind higher-priority work. Follows ordinary operational sequencing. Receives preferential scheduling because delay may affect downstream activity. Requires protected or immediate execution because delay may materially affect safety, vessel operations, gate commitments, customer commitments, or another critical process. Required for consistent competing-work prioritization. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7644f15b-5dc6-544c-b1eb-5f753fcbdfdd', '9add137f-1c70-5ed5-ae00-5329d683ffb4', '03f22f52-8c3a-540f-8208-5a14f876af26', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Container', 'Identifies the physical container being moved. Connects movement execution to equipment identity, size, type, ownership, condition, status, and current position. Exactly one Container is the subject of a movement. Container is the asset/current-state object; ContainerMovement is the event that changes its operational position or transport state. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bf14dcaa-cb65-5d54-acf2-a8fd7d4b6c5f', '9add137f-1c70-5ed5-ae00-5329d683ffb4', '82ac4c43-2d87-54f1-9658-4fd0e822749f', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Source Slot', 'Identifies the exact yard position occupied immediately before the movement when the move originates in a modeled yard slot. Supports occupancy release, validation, stack dependency analysis, travel planning, and historical reconstruction. Zero when the movement originates outside a yard slot, such as a gate-in or external discharge. Source slot is the physical starting position, not merely the facility or block containing the container.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('001018ce-4724-5649-975e-29896151366d', '9add137f-1c70-5ed5-ae00-5329d683ffb4', '386aa9ad-bb9a-551d-b78a-18e010896827', '57318b9f-2a6b-54e8-835c-025897f56ff2', 'Assigned To', 'Identifies the party responsible for executing the movement when responsibility is modeled at party level. Supports dispatch accountability, contractor management, workload, safety, and performance reporting. Optional because execution may instead be assigned through a specialized worker, vehicle, crane, or external execution model. Party provides identity; specialized assignment entities can provide the operational execution details.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
