VALUES ('b94e7a14-b969-50d1-9784-62ed2aed8234', (SELECT sys_role_id FROM sys_role WHERE name = 'User'), '969bc94c-d130-593c-ab8e-c87d212f7f74', 'c280a70d-0b2d-552c-bccb-1df9ea53209b', 'R', TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
